import { test, expect } from '@playwright/test';

test.describe('Direct Task Creation Flow', () => {
  // Use the credentials generated by the seed script
  const REQUESTER_EMAIL = 'requester@direct.com';
  const PASSWORD = 'password123';

  test('Requester can create a direct task successfully', async ({ page }) => {
    // 1. Navigate to the login page (adjust the URL port as needed for your local frontend)
    await page.goto('http://localhost:3000/login'); 
    
    // 2. Login as the Requester
    await page.fill('input[name="email"]', REQUESTER_EMAIL);
    // Assuming your password input has name="password" or type="password"
    await page.fill('input[type="password"]', PASSWORD);
    await page.click('button[type="submit"]');

    // 3. Wait for the dashboard/home to load indicating successful login
    // Adjust selector based on what indicates a logged in state
    await expect(page.locator('text=Dashboard').first()).toBeVisible({ timeout: 10000 });

    // 4. Navigate to the Marketplace / Providers list
    // Click the navigation link to the marketplace
    await page.click('text=Marketplace'); 
    
    // 5. Find the Provider and click 'Direct Request'
    // This depends heavily on your UI. We assume there's a card/list item for 'Direct Provider'
    await page.click('text=Direct Provider');
    await page.click('button:has-text("Send Direct Request")');

    // 6. Fill out the Direct Task Form
    // Wait for the modal or page containing the form to load
    await expect(page.locator('form').first()).toBeVisible();

    // Select the requester website (from the seeded data)
    await page.selectOption('select[name="requesterWebsiteId"]', { index: 1 }); 
    
    // Fill the required text fields
    await page.fill('input[name="projectTitle"]', 'Direct Guest post for fintech campaign');
    await page.fill('input[name="targetUrl"]', 'https://requester-test.com/target-page');
    await page.fill('input[name="anchorText"]', 'best fintech startup');
    await page.fill('textarea[name="placementGuidelines"]', 'Please place in the second paragraph with natural context.');
    
    // Select dropdown values matching the expected ENUMs
    await page.selectOption('select[name="placementType"]', 'BACKLINK_INSERTION'); 
    await page.selectOption('select[name="linkAttribute"]', 'DOFOLLOW'); 
    await page.selectOption('select[name="requestedDeadlineDays"]', '7');
    
    // Select the wallet type (We seeded EARNED credits)
    await page.selectOption('select[name="walletType"]', 'EARNED'); 
    
    // 7. Submit request
    await page.click('button:has-text("Submit Request")');

    // 8. Verify success message or redirection
    // Adjust this to match whatever toast or redirect happens upon success
    await expect(page.locator('text=Request Sent Successfully')).toBeVisible();
    
    // 9. Verify it shows up in sent requests tab
    await page.click('text=My Requests');
    await expect(page.locator('text=Direct Guest post for fintech campaign')).toBeVisible();
  });
});
